<?php
declare(strict_types=1);namespace Haerriz\AgenticCommerce\Model\Resolver;
use Haerriz\AgenticCommerce\Model\Cart\CartService;use Haerriz\AgenticCommerce\Model\GraphQl\CustomerContext;use Haerriz\AgenticCommerce\Model\GraphQl\IdempotentExecutor;use Magento\Framework\Exception\{AuthorizationException,LocalizedException};use Magento\Framework\GraphQl\Config\Element\Field;use Magento\Framework\GraphQl\Exception\{GraphQlAuthorizationException,GraphQlInputException};use Magento\Framework\GraphQl\Query\ResolverInterface;use Magento\Framework\GraphQl\Schema\Type\ResolveInfo;
class ClearCartResolver implements ResolverInterface{public function __construct(private CartService $cartService,private CustomerContext $customerContext,private IdempotentExecutor $idempotency){}public function resolve(Field $field,$context,ResolveInfo $info,array $value=null,array $args=null){$i=(array)($args['input']??[]);$identity=$this->customerContext->identityForTool($context,$i['client_id']??null,'clear_cart');try{return$this->idempotency->execute('clear_cart',$i,$identity,fn():array=>$this->cartService->clear($identity,isset($i['cart_id'])?(string)$i['cart_id']:null));}catch(AuthorizationException $e){throw new GraphQlAuthorizationException(__($e->getMessage()));}catch(LocalizedException $e){throw new GraphQlInputException(__($e->getMessage()));}}}
